<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $filter = sd_social_current_filter(); $page = isset( $_GET['paged'] ) ? absint( $_GET['paged'] ) : 1; $result = sd_social_activity_query( $filter, $page, 10 ); ?><div class="sd-social-layout <?php echo sd_get_option( 'sd_social_sidebar' ) ? '' : 'sd-social-no-sidebar'; ?>"><aside class="sd-social-left"><?php get_template_part( 'template-parts/social/feed-sidebar' ); ?></aside><section class="sd-social-center"><div class="sd-card sd-card-body"><?php get_template_part( 'template-parts/social/activity-composer' ); ?></div><?php get_template_part( 'template-parts/social/feed-filters' ); ?><?php if ( ! empty( $result['activities'] ) ) : ?><div class="sd-activity-feed"><?php foreach ( $result['activities'] as $activity ) { get_template_part( 'template-parts/social/activity-card', null, array( 'activity' => $activity ) ); } ?></div><?php else : get_template_part( 'template-parts/social/activity-empty' ); endif; ?></section><aside class="sd-social-right"><?php if ( is_user_logged_in() && function_exists( 'sd_core_recommend_members' ) ) : ?><div class="sd-card sd-card-body"><h3><?php esc_html_e( 'People you may know', 'social-discovery' ); ?></h3><?php foreach ( sd_core_recommend_members( get_current_user_id(), sd_get_option( 'sd_social_suggested_members' ) ) as $recommendation ) : ?><a class="sd-mini-member" href="<?php echo esc_url( sd_get_member_url( $recommendation['user']->ID ) ); ?>"><img src="<?php echo esc_url( sd_avatar( $recommendation['user']->ID, 36 ) ); ?>" alt=""><span><?php echo esc_html( sd_member_display_name( $recommendation['user']->ID ) ); ?><small><?php echo esc_html( $recommendation['shared_interests'] ); ?> <?php esc_html_e( 'shared interests', 'social-discovery' ); ?></small></span></a><?php endforeach; ?></div><?php endif; ?></aside></div>
